func And(predicates ...predicate.UbaEvent) predicate.UbaEvent {
	return predicate.UbaEvent(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UbaEvent) predicate.UbaEvent {
	return predicate.UbaEvent(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UbaEvent) predicate.UbaEvent {
	return predicate.UbaEvent(sql.NotPredicates(p))
}
